DECLARE
  TYPE order_cur_t IS REF CURSOR RETURN orders%ROWTYPE;  -- strong
  c_strong order_cur_t;
  c_weak   SYS_REFCURSOR;                                -- weak
BEGIN
  OPEN c_strong FOR SELECT * FROM orders;  -- must return orders%ROWTYPE
  OPEN c_weak   FOR SELECT city, COUNT(*) FROM orders GROUP BY city;  -- any query
  CLOSE c_strong;
  CLOSE c_weak;
END;
/

