DECLARE
  c_orders  SYS_REFCURSOR;
  v_id      orders.order_id%TYPE;
  v_name    orders.customer_name%TYPE;
  v_amount  orders.amount%TYPE;
BEGIN
  OPEN c_orders FOR
    SELECT order_id, customer_name, amount
      FROM orders
     WHERE city = 'Pune'
     ORDER BY order_id;

  LOOP
    FETCH c_orders INTO v_id, v_name, v_amount;
    EXIT WHEN c_orders%NOTFOUND;
    DBMS_OUTPUT.PUT_LINE(v_id || '  ' || RPAD(v_name, 12) || v_amount);
  END LOOP;

  DBMS_OUTPUT.PUT_LINE('Rows fetched: ' || c_orders%ROWCOUNT);
  CLOSE c_orders;
END;
/

