CREATE OR REPLACE FUNCTION search_orders (
  p_city       IN VARCHAR2,
  p_min_amount IN NUMBER,
  p_sort       IN VARCHAR2   -- 'AMOUNT' or 'ID'
) RETURN SYS_REFCURSOR
IS
  c_result SYS_REFCURSOR;
  v_sql    VARCHAR2(500);
BEGIN
  v_sql := 'SELECT order_id, customer_name, amount
              FROM orders
             WHERE city = :city
               AND amount >= :min_amt
             ORDER BY '
           || CASE p_sort
                WHEN 'AMOUNT' THEN 'amount DESC'
                ELSE 'order_id'
              END;

  OPEN c_result FOR v_sql USING p_city, p_min_amount;
  RETURN c_result;
END search_orders;
/

VARIABLE rc REFCURSOR
EXEC :rc := search_orders('Pune', 3000, 'AMOUNT');
PRINT rc

DECLARE
  TYPE t_ids  IS TABLE OF orders.order_id%TYPE;
  TYPE t_amts IS TABLE OF orders.amount%TYPE;
  c      SYS_REFCURSOR;
  l_ids  t_ids;
  l_amts t_amts;
BEGIN
  OPEN c FOR SELECT order_id, amount FROM orders ORDER BY order_id;
  LOOP
    FETCH c BULK COLLECT INTO l_ids, l_amts LIMIT 4;
    EXIT WHEN l_ids.COUNT = 0;
    DBMS_OUTPUT.PUT_LINE('Batch of ' || l_ids.COUNT ||
                         ' rows, first id ' || l_ids(1));
  END LOOP;
  CLOSE c;
END;
/

CREATE OR REPLACE PROCEDURE order_summary
IS
  rc1 SYS_REFCURSOR;
  rc2 SYS_REFCURSOR;
BEGIN
  OPEN rc1 FOR
    SELECT status, COUNT(*) AS orders
      FROM orders GROUP BY status ORDER BY status;
  DBMS_SQL.RETURN_RESULT(rc1);

  OPEN rc2 FOR
    SELECT city, SUM(amount) AS total_amount
      FROM orders GROUP BY city ORDER BY city;
  DBMS_SQL.RETURN_RESULT(rc2);
END order_summary;
/

EXEC order_summary

