CREATE OR REPLACE FUNCTION get_orders(
  p_city VARCHAR2) RETURN SYS_REFCURSOR
IS
  c SYS_REFCURSOR;
BEGIN
  OPEN c FOR SELECT order_id, amount
    FROM orders WHERE city = p_city;
  RETURN c;  -- caller closes it
END;

LOOP
  FETCH c INTO v_id, v_amount;
  EXIT WHEN c%NOTFOUND;
  DBMS_OUTPUT.PUT_LINE(v_id);
END LOOP;
CLOSE c;
